files.test/acceptance/support/build-runs-comma:
'use strict';

// Fake ChatGPT script: the same shell command twice in one attempt. The second call is only
// reached when the Build went on after the first result.
module.exports = function buildRunsCommandTwice({ toolResults, args, ordinal, functionCall, calls, correct }) {
  const command = args.command || 'true';
  const done = toolResults.filter(item => item.kind === 'build' && item.name === 'shell' && item.args?.command === command).length;
  if (done < 2) return { items: [functionCall('shell', { command }, `build_shell_${done + 1}_${ordinal}`)] };
  return calls(correct);
};

